import sys

def calc(expr: str) -> int | str:
    sys.setrecursionlimit(100000)
    s = expr
    n = len(s)
    i = 0

    class Error(Exception):
        pass

    def skip():
        nonlocal i
        while i < n and s[i] == ' ':
            i += 1

    def peek():
        skip()
        return s[i] if i < n else ''

    def parse_atom():
        nonlocal i
        c = peek()
        if c == '(':
            i += 1
            v = parse_expr()
            if peek() == ')':
                i += 1
            return v
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    def parse_power():
        nonlocal i
        base = parse_atom()
        if peek() == '^':
            i += 1
            exp = parse_unary()
            if exp < 0:
                raise Error()
            base = base ** exp
        return base

    def parse_unary():
        nonlocal i
        neg = False
        while peek() == '-':
            i += 1
            neg = not neg
        v = parse_power()
        return -v if neg else v

    def parse_term():
        nonlocal i
        v = parse_unary()
        while True:
            c = peek()
            if c == '*':
                i += 1
                v *= parse_unary()
            elif c == '/':
                i += 1
                b = parse_unary()
                if b == 0:
                    raise Error()
                q = abs(v) // abs(b)
                if (v < 0) != (b < 0):
                    q = -q
                v = q
            elif c == '%':
                i += 1
                b = parse_unary()
                if b == 0:
                    raise Error()
                q = abs(v) // abs(b)
                if (v < 0) != (b < 0):
                    q = -q
                v = v - b * q
            else:
                return v

    def parse_expr():
        nonlocal i
        v = parse_term()
        while True:
            c = peek()
            if c == '+':
                i += 1
                v += parse_term()
            elif c == '-':
                i += 1
                v -= parse_term()
            else:
                return v

    try:
        skip()
        return parse_expr()
    except Error:
        return "error"
